import React, { useState, useEffect } from 'react';
import orderService from '../services/orderService';

const ReadyOrders = () => {
  const [orders, setOrders] = useState([]);
  const [fadeOutOrders, setFadeOutOrders] = useState(new Set());
  const [scaleInOrders, setScaleInOrders] = useState(new Set());

  useEffect(() => {
    // Initial load
    setOrders(orderService.getReadyOrders());
    
    // Set up automatic updates every 3 seconds
    const interval = setInterval(() => {
      const previousOrderIds = orders.map(order => order.id);
      
      // Simulate order updates
      orderService.simulateOrderUpdates();
      const newOrders = orderService.getReadyOrders();
      const currentOrderIds = newOrders.map(order => order.id);
      
      // Find orders that were removed
      const removedOrderIds = orderService.getRemovedOrders(currentOrderIds, previousOrderIds);
      
      // Find new orders
      const newOrderIds = currentOrderIds.filter(id => !previousOrderIds.includes(id));
      
      if (removedOrderIds.length > 0) {
        // Start fade out animation for removed orders
        setFadeOutOrders(new Set(removedOrderIds));
        
        // Remove orders after fade animation completes
        setTimeout(() => {
          setOrders(newOrders);
          setFadeOutOrders(new Set());
        }, 500); // 500ms fade duration
      } else {
        // Just update orders if no removals
        setOrders(newOrders);
      }
      
      // Handle new orders with scale-in animation
      if (newOrderIds.length > 0) {
        setScaleInOrders(new Set(newOrderIds));
        setTimeout(() => {
          setScaleInOrders(new Set());
        }, 600); // 600ms scale duration
      }
    }, 3000);

    return () => clearInterval(interval);
  }, [orders]);

  return (
    <div className="w-full h-full">
      <h2 className="text-2xl xl:text-6xl font-bold text-black mb-6 text-center">
        Ready Orders
      </h2>
      
      <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-4 gap-4 xl:gap-6 h-full">
        {orders.map((order) => (
          <div 
            key={order.id} 
            className={`bg-white border-2 border-gray-300 rounded-lg p-4 xl:p-6 shadow-md flex-grow flex flex-col transition-opacity duration-500 ${
              fadeOutOrders.has(order.id) ? 'opacity-0' : 'opacity-100'
            }`}
          >
            {/* Token Number */}
            <div className="text-center mb-4">
              <div className="text-3xl xl:text-6xl font-bold text-black">
                {order.tokenNumber}
              </div>
            </div>

            {/* Customer Name */}
            <div className="text-center mb-4">
              <div className="text-lg xl:text-3xl font-semibold text-gray-800">
                {order.customerName}
              </div>
            </div>

            {/* Items List */}
            <div className="flex-grow mb-4">
              <div className="text-sm xl:text-xl text-gray-600 text-center">
                {order.items.map((item, index) => (
                  <div key={index} className="mb-1">
                    {item}
                  </div>
                ))}
              </div>
            </div>

            {/* Cost and Ready Time */}
            <div className="border-t border-gray-200 pt-4 mt-auto">
              <div className="text-center space-y-2">
                <div className="text-lg xl:text-3xl font-bold text-green-600">
                  ${order.cost.toFixed(2)}
                </div>
                <div className="text-sm xl:text-xl text-gray-500">
                  Ready: {order.readyTime}
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
      
      {/* Last Update Indicator */}
      <div className="text-center mt-4 text-xs text-gray-400">
        Last updated: {new Date(lastUpdateTime).toLocaleTimeString()}
      </div>
    </div>
  );
};

export default ReadyOrders;
